/* Customer business code split by dependency; shared records and existing handlers stay compatible. */
'use strict';
function apFilterClear(){apSheet.filter={q:apFilter().q,store:'',reason:'',urgency:'',status:'',from:'',to:''};document.querySelectorAll('#apMobileSheet select,#apMobileSheet input').forEach(el=>el.value='')}
function apFilterApply(){let f=apSheet?.filter;if(!f)return;if(f.from&&f.to&&f.from>f.to){apActionError('结束日期不能早于开始日期');return}apFilters[apView]=clone(f);apDismiss();apSearch()}
function apMergePlan(a){return a.review?.status==='approved'&&a.review.approvedPlan?a.review.approvedPlan:a.review?.submittedPlan||a.plan}
function apMergeReview(a,plan=apMergePlan(a)){
 const pair=a.pair,impact=mrImpact(pair,plan),submitted=a.review?.submittedPlan||a.plan,original=mrImpact(pair,submitted),record=state.mergeRecords.find(r=>r.id===a.recordId);
 const after=record?.snapshot?.after||impact.after,active=impact.all.filter(mrActive),historical=impact.all.filter(o=>!mrActive(o)),recommend=mrRecommend(pair,a.rule);
 const suggested=mrPlan(pair,a.rule);suggested.mainId=plan.mainId;
 if(pair.length===2){let arbitration=mrArbitration(pair,plan.mainId,a.rule);suggested.action=['keepMain','keepChild','keepBoth'].includes(arbitration.action)?arbitration.action:'keepBoth'}
 const suggestion=mrImpact(pair,suggested),changes=[],person=id=>pair.find(c=>c.id===id),label=c=>c?c.name+' · '+uiId(c.id):'未记录';
 if(impact.main.id!==original.main.id)changes.push(['主档案',label(original.main),label(impact.main)]);
 for(let [key,title] of [['name','合并后姓名'],['phone','主手机号'],['gender','性别'],['birthday','生日'],['remark','备注'],['store','档案门店'],['consultant','档案归属客服'],['customerType','客户类型']])if(String(original.after[key]||'')!==String(after[key]||''))changes.push([title,key==='phone'?uiPhone(original.after[key]):original.after[key]||'未填写',key==='phone'?uiPhone(after[key]):after[key]||'未填写']);
 for(let o of active){let from=original.returned.some(x=>x.id===o.id),to=impact.returned.some(x=>x.id===o.id);if(from!==to)changes.push(['订单 '+uiId(o.id),from?'合并流退':'保留订单',to?'合并流退':'保留订单'])}
 const heads=apMergeHeadcounts(pair,after),changedHeads=heads.filter(x=>x.beforeBooking!==x.afterBooking||x.beforeArrival!==x.afterArrival);
 const stale=a.review?.status==='pending'?Object.entries(a.review.baseline||{}).filter(([id,data])=>JSON.stringify(state.mergeCustomers.find(c=>c.id===id)||null)!==data).map(([id])=>label(person(id))):[];
 return {a,pair,plan,impact,submitted,original,record,after,active,historical,recommend,suggestion,changes,heads,changedHeads,stale,gaps:apMergeDataGaps(pair),label,person};
}
function apMergeDataGaps(pair){
 const rows=[['剩余项目权益','当前合并方案未提供独立的剩余、冻结、已退权益核对结果，项目记录条数不能作为剩余资产数量。']];
 const missing=pair.filter(c=>!Array.isArray(c.payments));
 if(missing.length)rows.push(['支付明细',missing.map(c=>esc(c.name)+' · '+uiId(c.id)).join('、')+'未保存独立支付流水；资金预估包含订单预约金、尾款字段推导，不能作为到账核对结论']);
 const wallets=pair.map(c=>({c,check:pcWalletCheck(c)})).filter(x=>Number(x.c.white)!==0&&!x.check.ok);
 if(wallets.length)rows.push(['白条核对',wallets.map(({c,check})=>esc(c.name)+' · '+uiId(c.id)+'：'+(!check.known?'余额 '+money(c.white)+'，缺少流水明细':'余额与流水差额 '+money(check.diff))).join('<br>')]);
 if(pair.some(c=>Number(c.recharge)>0))rows.push(['充值核对','当前方案仅保存充值余额汇总，未提供独立充值流水核对结果']);
 return rows;
}
function apMergeHeadcounts(pair,after){
 const keys=[...new Set(pair.flatMap(c=>(c.orders||[]).map(o=>JSON.stringify([o.consultant||c.consultant||'',o.store||c.store||'']))))];
 const matches=(c,o,by,store)=>(o.consultant||c.consultant||'')===by&&(o.store||c.store||'')===store;
 const count=(customers,by,store,arrival)=>customers.filter(c=>(c.orders||[]).some(o=>matches(c,o,by,store)&&(arrival?['已到店','已完成'].includes(o.status):mrActive(o)))).length;
 return keys.map(key=>{let [by,store]=JSON.parse(key),orders=pcUnique(pair.flatMap(c=>(c.orders||[]).filter(o=>matches(c,o,by,store))));return {by,store,orders,beforeBooking:count(pair,by,store,false),afterBooking:count([after],by,store,false),beforeArrival:count(pair,by,store,true),afterArrival:count([after],by,store,true)}}).sort((a,b)=>Number(b.beforeBooking!==b.afterBooking||b.beforeArrival!==b.afterArrival)-Number(a.beforeBooking!==a.afterBooking||a.beforeArrival!==a.afterArrival));
}
function apMergeIdentityRows(a){
 const same=maIdentityRows(a.pair).filter(x=>x.sources.length>1),rows=same.map(x=>[({phone:'共享手机号',union:'共享 UnionID',external:'共享企微标识'})[x.type],esc(x.type==='phone'?uiPhone(x.value):x.value)+'<div class="tiny muted">'+x.sources.map(c=>esc(c.name)+' · '+uiId(c.id)).join('、')+'</div>']);
 if(!rows.length)rows.push(['共同身份标识','提交资料未记录共有的手机号或微信标识']);
 for(let [key,label] of [['gender','性别差异'],['birthday','生日差异']])if(new Set(a.pair.map(c=>c[key]).filter(Boolean)).size>1)rows.push([label,a.pair.map(c=>esc(c.name)+'：'+esc(c[key]||'未填写')).join('；')]);
 return rows;
}
function apMergeEvidenceHtml(a){return (a.evidence||[]).length?(a.evidence||[]).map(x=>{let name=typeof x==='string'?x:x.name;return '<div class="ap-file">'+icon('file')+'<span>'+esc(name)+'</span>'+btn('查看',`apEvidence(${mrQuote(name)})`,'text')+'</div>'}).join(''):'<p class="small muted">未上传核实材料，需结合申请说明与档案资料判断。</p>'}
function apMergeOrderEffect(v,o){
 if(!mrActive(o))return '历史终态保留，原订单与支付记录迁入主档案';
 if(!v.impact.returned.some(x=>x.id===o.id))return '保持原状态、预约、预约人员和接待人员';
 const cancelled=v.impact.cancelled.some(x=>x.id===o.id),at=o.appointmentAt||o.scheduledAt;
 return (cancelled?'取消排客 '+(at||'时间未记录'):o.status==='已到店'?'合并到店流退，保留实际到店历史':'合并预约流退')+'；原收款保留，不自动退款';
}
function apMergeHeadSummary(v){return v.changedHeads.length?v.changedHeads.map(x=>(x.by||'客服未记录')+' / '+(x.store||'门店未记录')+'：预约 '+x.beforeBooking+'→'+x.afterBooking+'，到店 '+x.beforeArrival+'→'+x.afterArrival).join('；'):'按现有订单口径，客服与门店预约、到店人头无变化'}
function apMergeKeyFacts(v){
 const {impact,after,active,historical,a}=v;
 let rows=[['参与档案',v.pair.map(c=>esc(v.label(c))).join('、')],['保留主档案',esc(v.label(impact.main))+'；沿用此档案 ID'],['主档案依据',esc(v.plan.mainReason||'申请未填写指定依据')],['合并后资料',esc(after.name)+' · '+esc(uiPhone(after.phone))],['进行中订单',active.length+' 笔：保留 '+(active.length-impact.returned.length)+' 笔，合并流退 '+impact.returned.length+' 笔'],['历史订单',historical.length+' 笔全部保留，原终态不变'],['取消排客',impact.cancelled.length?impact.cancelled.map(o=>'订单 '+uiId(o.id)+' · '+esc(o.appointmentAt||o.scheduledAt||'时间未记录')).join('<br>'):'无'],['人头变化',esc(apMergeHeadSummary(v))]];
 if(v.stale.length)rows.push(['提交后变化',esc(v.stale.join('、'))+'已有更新；请驳回，由申请人核实后重新提交']);
 return rows;
}
function apMergeSupplement(a){
 if(!a.manualRequests?.length)return '';
 return apSection('补充申请',table(['申请人 / 时间','补充说明','补充方案 / 材料'],a.manualRequests.map(x=>{let im=x.proposal?.pair?.length>1?mrImpact(x.proposal.pair,x.proposal.plan):null;return [esc(x.author)+'<div class="tiny muted">'+esc(x.time)+'</div>',esc(x.reason||'未填写'),(im?'拟保留 '+esc(im.main.name)+' · '+uiId(im.main.id)+'；流退 '+im.returned.length+' 笔订单<br>':'')+(x.evidence||[]).map(esc).join('、')]}))+'<p class="small muted">补充申请用于审核参考，不自动覆盖本次提交方案。</p>');
}
function apMergeSummary(a){
 const v=apMergeReview(a),r=a.review;
 return apSection('申请信息',apFacts([['申请人',esc(r?.submittedBy||a.author)],['提交时间',esc(r?.submittedAt||a.time)],['申请门店',esc(a.store)],['申请来源',esc(a.source||'人工提交')],['当前节点',apBadge(apStatus(a,'merge'))],['处理人',esc(r?.assignee||a.approvedBy||'未记录')],['申请原因',esc(a.reasonType||'未填写原因分类')],['核实说明',esc(a.reason||'未填写')],['数据时点',esc(r?.submittedAt||a.time)+' · 提交时档案与订单快照']]))+
 apSection('本次合并方案',apFacts(apMergeKeyFacts(v)))+
 apMergeSupplement(a)+apSection('处理流程',table(['环节','办理人','状态','时间 / 说明'],apProcessNodes(a,'merge').map(n=>[esc(n.title),esc(n.actor),esc({done:'已完成',current:'办理中',future:'未开始',unknown:'未记录',rejected:'已驳回',failed:'执行失败'}[n.status]),esc(n.at||'—')+'<div class="tiny muted">'+esc(n.note)+'</div>'])))+apMergeRecords(a);
}
function apMergePeopleTable(v){
 const transition=(a,b)=>a+' → '+b+'（'+(b-a>0?'+':'')+(b-a)+'）';
 return apSection('客服与门店人头变化',table(['客服 / 门店','涉及订单','预约人头：合并前 → 后','到店人头：合并前 → 后'],v.heads.map(x=>[esc(x.by||'未记录')+'<div class="tiny muted">'+esc(x.store||'未记录')+'</div>',x.orders.map(o=>uiId(o.id)+(v.impact.returned.some(r=>r.id===o.id)?' · 合并流退':'')).join('<br>'),transition(x.beforeBooking,x.afterBooking),transition(x.beforeArrival,x.afterArrival)]))+'<p class="small muted">按订单客服、门店及客户档案去重预估；订单未记门店或客服时沿用原档案值。合并流退不计入流退考核，实际签到历史保留。此处不计算提成金额。</p>');
}
function apActionError(message){let el=$('#apMobileSheet .ap-action-error');if(el){el.hidden=false;el.textContent=message}else toast(message)}
function apProcessNodes(o,kind=apTask.kind){
 const r=o.review,events=r?.events||[],find=(name)=>events.findLast(e=>e.action===name),submitted=find('提交审核'),rejected=find('驳回'),hq=find('总部审核通过'),finance=find('财务加签通过'),approved=find('审核通过')||find('店长审核通过'),finished=find('财务确认调整单');
 const executed=!!(o.recordId||o.resultData),complete=kind==='merge'?!!o.recordId:o.status==='已完成',rows=[];
 const node=(key,title,status,actor,at='',note='')=>rows.push({key,title,status,actor:actor||'未记录',at:at||'',note});
 node('submitted','提交申请','done',submitted?.actor||r?.submittedBy||o.author,r?.submittedAt||o.submittedAt||o.time||o.date,'完整方案已提交');
 if(!r){node('review',kind==='merge'?'合并审核':'纠错审核',o.approvedAt?'done':'unknown',o.approvedBy||'历史资料未记录',o.approvedAt,o.approvedAt?'':'未保存完整审核节点，不推测历史审批人');}
 else if(kind==='correction'&&o.high){
  let firstDone=!!hq||r.status==='finance'||r.status==='approved',firstRejected=r.status==='rejected'&&!hq;
  node('hq','总部审核',firstRejected?'rejected':firstDone?'done':'current',hq?.actor||(firstRejected?rejected?.actor:r.status==='pending'?r.assignee:'市场部主管'),hq?.at||(firstRejected?rejected?.at:''),firstRejected?rejected?.note:hq?.note||'核对纠错依据与完整业务方案');
  node('finance','财务加签',r.status==='rejected'&&hq?'rejected':finance||r.status==='approved'?'done':r.status==='finance'?'current':'future',finance?.actor||(r.status==='finance'?r.assignee:r.status==='rejected'&&hq?rejected?.actor:'财务加签人'),finance?.at||(r.status==='rejected'&&hq?rejected?.at:''),r.status==='rejected'&&hq?rejected?.note:finance?.note||'核对冲销金额与资金归属');
 }else node('review',kind==='merge'?'合并审核':'店长审核',r.status==='rejected'?'rejected':r.status==='approved'?'done':'current',approved?.actor||rejected?.actor||r.assignee,approved?.at||rejected?.at,r.status==='rejected'?rejected?.note:approved?.note||'核对后确认完整处理方案');
 node('execution',kind==='merge'?'系统合并':'系统纠错',executed?'done':o.status==='执行失败'?'failed':r?.status==='approved'?'current':'future','系统',o.executedAt,executed?(kind==='merge'?'合并记录 '+uiId(o.recordId)+' 已生成':'业务归属已调整，纠错调整单已生成'):o.status==='执行失败'?o.execution?.error||r?.executionError:kind==='merge'?'全部审核通过后自动执行':'全部审核通过后，按方案建档并迁移当前业务');
 if(kind==='correction')node('result','调整单确认',complete?'done':executed?'current':'future',finished?.actor||o.completedBy||'财务加签人',finished?.at||o.completedAt,complete?o.financeOpinion||'客户业务、资金与员工业绩结果已确认':'核对执行结果与调整单后完成工单');
 if(r?.status==='rejected')for(let x of rows)if(x.status==='future')x.note='申请已驳回，后续节点不执行';
 return rows;
}
function apOperationEntries(o){
 let rows=(o.review?.events||[]).map(e=>({at:e.at,actor:e.actor,title:e.action,note:e.note||''}));
 for(let e of [...(o.logs||[])].reverse()){let title=e.content||e.action||e.title||'处理记录',actor=e.by||e.actor||'未记录';if(rows.some(x=>x.at===e.at&&x.actor===actor&&(/审核|核实/.test(title)&&/通过|驳回/.test(x.title)||x.title===title)))continue;rows.push({at:e.at,actor,title,note:e.before||e.after?[e.before,e.after].filter(Boolean).join(' → '):e.note||''})}
 if(o.executedAt&&!rows.some(x=>x.at===o.executedAt&&/执行|合并完成|纠错|调整单/.test(x.title)))rows.push({at:o.executedAt,actor:'系统',title:'系统执行完成',note:o.recordId?'生成合并记录 '+uiId(o.recordId):'生成纠错结果及调整单'});
 if(o.completedAt&&!rows.some(x=>/确认|完成/.test(x.title)&&x.at===o.completedAt))rows.push({at:o.completedAt,actor:o.completedBy||'未记录',title:'调整单确认',note:o.financeOpinion||'工单已完成'});
 let seen=new Set();return rows.map((x,i)=>({...x,index:i})).filter(x=>{let k=[x.at,x.actor,x.title,x.note].join('|');if(seen.has(k))return false;seen.add(k);return true}).sort((a,b)=>(b.at||'').localeCompare(a.at||'')||b.index-a.index);
}
function apMergeRecords(o){return contentModule('操作记录',body(table(['时间','操作人','操作','说明'],apOperationEntries(o).map(e=>[esc(e.at),esc(e.actor),esc(e.title),esc(e.note||'—')]))),'','ap-operation-card')}
function apShowRecords(){if(!apTask)return;apTask.mobileTab='plan';apTask.tab='summary';render();let mobile=apIsMobile(),card=$(mobile?'.ap-workspace .ap-operation-card':'#apReviewPanel .ap-operation-card'),scroller=$(mobile?'.ap-mobile-scroll':'#apReviewPanel .merge-drawer-body');if(card&&scroller)scroller.scrollTo({top:Math.max(0,scroller.scrollTop+card.getBoundingClientRect().top-scroller.getBoundingClientRect().top-(mobile?$('.ap-workspace>.ap-tabs')?.offsetHeight||0:0)-12)})}
function apBadge(s){return badge(s,['已合并','已完成','已通过'].includes(s)?'green':['已驳回','执行失败'].includes(s)?'red':s.includes('财务')||s.includes('确认')?'orange':'blue')}
function apAll(){return [...state.mergeApplications.filter(a=>a.review||a.recordId).map(o=>({kind:'merge',o})),...state.cases.filter(c=>c.review||c.submittedPlan||c.resultData||c.status==='已完成').map(o=>({kind:'correction',o}))]}
function apFilter(){return apFilters[apView]||=( {q:'',store:'',reason:'',urgency:'',status:'',from:'',to:''} )}
function apRows(){let f=apApplied[apView]||{},history=apView==='history';return apAll().filter(({kind,o})=>{let status=apStatus(o,kind),handled=o.review?o.review.events.some(e=>!['提交审核','提交完整方案'].includes(e.action)):!!(o.executedAt||o.resultData),date=history?(o.review?.events.at(-1)?.at||o.executedAt||o.date||o.time):(o.review?.submittedAt||o.time||o.date),names=kind==='merge'?o.pair.flatMap(c=>[c.name,c.id,c.phone]).join(' '):[o.name,o.subname,o.profileDraft?.name,o.id].join(' ');return (history?handled:kind===apView)&&(!f.status?(history||['待审核','待财务加签','待调整单确认','执行失败','系统执行中'].includes(status)):f.status==='all'||status===f.status)&&(!f.q||[names,o.id,o.reason].join(' ').toLowerCase().includes(uiQuery(f.q).toLowerCase()))&&(!f.store||(kind==='merge'?o.pair.some(c=>c.store===f.store):o.store===f.store))&&(!f.reason||(o.reasons||[]).includes(f.reason))&&(!f.urgency||(o.review?.urgency||'普通')===f.urgency)&&(!f.from||date.slice(0,10)>=f.from)&&(!f.to||date.slice(0,10)<=f.to)}).sort((a,b)=>(b.o.review?.submittedAt||b.o.time||b.o.date).localeCompare(a.o.review?.submittedAt||a.o.time||a.o.date))}
function apSwitch(view){apView=view;apPage=1;render()}
function apSearch(){apApplied[apView]=clone(apFilter());apPage=1;render()}
function apReset(){delete apFilters[apView];delete apApplied[apView];apPage=1;render()}
function apTabs(items,current,action,cls=''){return '<div class="ap-tabs '+cls+'" role="tablist">'+items.map(([k,t])=>'<button role="tab" aria-selected="'+(k===current)+'" class="'+(k===current?'active':'')+'" onclick="'+esc(action(k))+'">'+esc(t)+'</button>').join('')+'</div>'}
function apFiltersUI(mobile=false){let f=apFilter(),stores=[...new Set(apAll().flatMap(x=>x.kind==='merge'?x.o.pair.map(c=>c.store):[x.o.store]))],reasons=[...new Set(state.mergeApplications.flatMap(a=>a.reasons||[]))];return '<div class="ap-search"><input type="search" aria-label="搜索审核工单" placeholder="客户姓名、手机号或工单 ID" value="'+esc(f.q)+'" oninput="apFilter().q=this.value" onkeydown="if(event.key===\'Enter\')apSearch()">'+select([['','全部门店'],...stores],f.store,'aria-label="审核门店" onchange="apFilter().store=this.value"')+(apView==='merge'?select([['','全部拦截原因'],...reasons],f.reason,'aria-label="审核拦截原因" onchange="apFilter().reason=this.value"')+select([['','全部紧急程度'],'普通','紧急'],f.urgency,'aria-label="紧急程度" onchange="apFilter().urgency=this.value"'):'')+select([['',apView==='history'?'全部审核结果':'待处理'],['all','全部状态'],'待审核','待财务加签','待调整单确认','已驳回','已合并','已完成','执行失败'],f.status,'aria-label="审核结果" onchange="apFilter().status=this.value"')+(apView==='history'?'<label>审核日期<input type="date" aria-label="审核开始日期" value="'+f.from+'" onchange="apFilter().from=this.value"></label><label>至<input type="date" aria-label="审核结束日期" value="'+f.to+'" onchange="apFilter().to=this.value"></label>':'')+'<div class="actions">'+btn('搜索','apSearch()')+btn('重置','apReset()')+'</div></div>'}
function apTitle(o,kind){return kind==='merge'?o.pair.map(c=>c.name).join(' + '):o.name+' · '+o.reason}
